1	// Minimal port of Python argparse for exactly one required option:
2	//   --domain DOMAIN  (plus -h/--help)
3	// Mirrors argparse behaviors: prefix abbreviation of long options,
4	// `--domain=VALUE` form, error -> stderr + exit(2), help -> stdout + exit(0).
5	
6	const LONG_OPTIONS = ['--help', '--domain'];
7	
8	function usageLine(prog) {
9	  return `usage: ${prog} [-h] --domain DOMAIN`;
10	}
11	
12	function errorExit(prog, message) {
13	  process.stderr.write(`${usageLine(prog)}\n`);
14	  process.stderr.write(`${prog}: error: ${message}\n`);
15	  process.exit(2);
16	}
17	
18	function printHelp(prog) {
19	  const lines = [
20	    usageLine(prog),
21	    '',
22	    'options:',
23	    '  -h, --help       show this help message and exit',
24	    '  --domain DOMAIN',
25	  ];
26	  process.stdout.write(lines.join('\n') + '\n');
27	  process.exit(0);
28	}
29	
30	// Resolve a long-option token (like "--dom") to a canonical option name.
31	// argparse allows any unambiguous prefix; ambiguous prefixes error out.
32	function resolveLongOption(token, prog) {
33	  const eq = token.indexOf('=');
34	  const name = eq === -1 ? token : token.slice(0, eq);
35	  const explicitValue = eq === -1 ? null : token.slice(eq + 1);
36	
37	  if (LONG_OPTIONS.includes(name)) {
38	    return { name, explicitValue };
39	  }
40	  const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
41	  if (matches.length === 1) {
42	    return { name: matches[0], explicitValue };
43	  }
44	  if (matches.length > 1) {
45	    errorExit(prog, `ambiguous option: ${name} could match ${matches.join(', ')}`);
46	  }
47	  return null; // unknown
48	}
49	
50	function looksLikeOption(value) {
51	  // argparse treats a token starting with '-' as an option (not a value),
52	  // unless it is a negative number; we have no numeric options here.
53	  return value.length > 1 && value.startsWith('-');
54	}
55	
56	export function parseDomainArg(argv, prog) {
57	  let domain;
58	  const unrecognized = [];
59	
60	  let i = 0;
61	  while (i < argv.length) {
62	    const token = argv[i];
63	
64	    if (token === '-h') {
65	      printHelp(prog);
66	    }
67	
68	    if (token.startsWith('--')) {
69	      const resolved = resolveLongOption(token, prog);
70	      if (resolved === null) {
71	        unrecognized.push(token);
72	        i += 1;
73	        continue;
74	      }
75	      if (resolved.name === '--help') {
76	        printHelp(prog);
77	      }
78	      // resolved.name === '--domain'
79	      if (resolved.explicitValue !== null) {
80	        domain = resolved.explicitValue;
81	      } else {
82	        const next = argv[i + 1];
83	        if (next === undefined || looksLikeOption(next)) {
84	          errorExit(prog, 'argument --domain: expected one argument');
85	        }
86	        domain = next;
87	        i += 1;
88	      }
89	      i += 1;
90	      continue;
91	    }
92	
93	    // Short option or positional: nothing else is defined.
94	    unrecognized.push(token);
95	    i += 1;
96	  }
97	
98	  if (unrecognized.length > 0) {
99	    errorExit(prog, `unrecognized arguments: ${unrecognized.join(' ')}`);
100	  }
101	  if (domain === undefined) {
102	    errorExit(prog, 'the following arguments are required: --domain');
103	  }
104	  return domain;
105	}

